import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 제목 최대 길이는 approval_document.title(500)과 같다.
const MAX_TITLE = 500;
// 가정: 본문 요약에 쓰는 최대 글자 수.
const MAX_SUMMARY = 300;

@Controller('api/v1')
export class FnSfr04402Controller {
  @Post('/approval-documents/ai-drafts')
  @HttpCode(200)
  async generateApprovalDocumentAiDraft(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const rawTitle = data['title'];
    const rawBody = data['body'];
    if (rawTitle !== undefined && rawTitle !== null && typeof rawTitle !== 'string') {
      throw new ApiError(400, 'VALIDATION_FAILED', '제목은 글자로 입력하세요.');
    }
    if (rawBody !== undefined && rawBody !== null && typeof rawBody !== 'string') {
      throw new ApiError(400, 'VALIDATION_FAILED', '본문은 글자로 입력하세요.');
    }
    const title = (rawTitle ?? '').trim();
    if (title.length > MAX_TITLE) {
      throw new ApiError(400, 'VALIDATION_FAILED', '제목은 500자 이내로 입력하세요.');
    }
    const plainBody = (rawBody ?? '')
      .replace(/<[^>]*>/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
    if (title === '' && plainBody === '') {
      throw new ApiError(422, 'AI_DRAFT_INPUT_REQUIRED', '제목이나 본문을 입력해야 AI 추천을 받을 수 있습니다.');
    }
    try {
      // 입력은 외부로 보내지 않고 이 서버 안에서만 처리한다. 저장·자동 확정은 하지 않는다.
      const subject = title !== '' ? title : plainBody.slice(0, 50);
      const summary = plainBody.slice(0, MAX_SUMMARY);
      const suggestedPhrases: string[] = [
        subject + ' 건에 대하여 아래와 같이 결재를 요청드립니다.',
        '위 건에 대해 검토 후 승인해 주시기 바랍니다.',
        '관련 내용은 아래와 같으니 확인 부탁드립니다.',
        '업무 진행에 차질이 없도록 신속한 결재를 부탁드립니다.',
      ];
      if (summary !== '') {
        suggestedPhrases.push('주요 내용: ' + summary.slice(0, 80));
      }
      const lines: string[] = [];
      lines.push('제목: ' + subject);
      lines.push('');
      lines.push('1. 목적');
      lines.push('   ' + subject + ' 건을 추진하고자 합니다.');
      lines.push('');
      lines.push('2. 내용');
      lines.push('   ' + (summary !== '' ? summary : '(세부 내용을 작성하세요.)'));
      lines.push('');
      lines.push('3. 요청 사항');
      lines.push('   위와 같이 기안하오니 검토 후 결재하여 주시기 바랍니다.');
      const draftText = lines.join('\n');
      return { suggestedPhrases, draftText };
    } catch (e) {
      if (e instanceof ApiError) {
        throw e;
      }
      throw new ApiError(502, 'AI_DRAFT_GENERATION_FAILED', 'AI 추천을 생성하지 못했습니다. 잠시 뒤 다시 시도하거나 직접 작성하세요.');
    }
  }
}

