import { useState } from 'react';
import {
  Band,
  DataTable,
  DateText,
  Drawer,
  Field,
  Form,
  Num,
  Pager,
  Tiles,
  TextInput,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

interface AiResult {
  suggestedPhrases: string[];
  draftText: string;
}

const SIZE = 5;

export default function FnSfr04402Page({ role, notify }: PageProps) {
  const [open, setOpen] = useState(false);
  const [title, setTitle] = useState('');
  const [body, setBody] = useState('');
  const [result, setResult] = useState<AiResult | undefined>(undefined);
  const [draft, setDraft] = useState('');
  const [history, setHistory] = useState<Row[]>([]);
  const [page, setPage] = useState(0);

  function openDrawer() {
    setTitle('');
    setBody('');
    setResult(undefined);
    setDraft('');
    setOpen(true);
  }

  async function generate() {
    if (title.trim() === '' && body.trim() === '') {
      throw new Error('제목이나 본문 중 하나는 입력하세요.');
    }
    const res = await call<AiResult>('POST', '/approval-documents/ai-drafts', role, { title, body });
    setResult(res);
    setDraft(res.draftText);
    notify('AI 추천을 생성했습니다.');
  }

  function addPhrase(phrase: string) {
    setDraft(draft === '' ? phrase : draft + '\n' + phrase);
  }

  async function apply() {
    if (draft.trim() === '') {
      throw new Error('반영할 내용을 입력하세요.');
    }
    const row: Row = {
      id: history.length + 1,
      title: title,
      text: draft,
      appliedAt: new Date().toISOString(),
    };
    setHistory([row, ...history]);
    setPage(0);
    setOpen(false);
    notify('기안문에 반영했습니다.');
  }

  const rows = history.slice(page * SIZE, page * SIZE + SIZE);

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>반영 건수</h2>
        <Tiles items={[['이 화면에서 반영', <Num value={history.length} />]]} />
      </section>
      <section className="box span-8">
        <h2>AI 작성 지원</h2>
        <p>제목·본문을 바탕으로 추천 문구와 초안을 받아 선택·수정한 뒤 반영합니다. 자동으로 확정되지 않습니다.</p>
        <button type="button" onClick={openDrawer}>AI 작성 지원 요청</button>
      </section>
      <section className="box span-12">
        <h2>반영한 초안</h2>
        <Band total={history.length} />
        <DataTable
          columns={[
            { key: 'title', label: '기안자가 입력한 제목' },
            { key: 'text', label: '반영한 초안' },
            { key: 'appliedAt', label: '반영 시각', render: (r) => <DateText value={r['appliedAt']} time /> },
          ]}
          rows={rows}
          empty="반영한 초안이 없습니다."
        />
        <Pager page={page} size={SIZE} total={history.length} onPage={setPage} />
      </section>
      {open && (
        <Drawer title="AI 작성 지원" onClose={() => setOpen(false)}>
          <Form onSubmit={generate} submit="추천 받기" note="실패해도 직접 작성을 계속할 수 있습니다.">
            <Field label="기안자가 입력한 제목" wide>
              <TextInput value={title} onChange={setTitle} />
            </Field>
            <Field label="작성 중인 기안문 본문" wide>
              <TextInput value={body} onChange={setBody} multiline />
            </Field>
          </Form>
          {result && (
            <div>
              <h3>AI가 제안하는 추천 문구</h3>
              <ul>
                {result.suggestedPhrases.map((p, i) => (
                  <li key={i}>
                    {p}{' '}
                    <button type="button" onClick={() => addPhrase(p)}>초안에 추가</button>
                  </li>
                ))}
              </ul>
              <Form onSubmit={apply} submit="기안문에 반영">
                <Field label="AI가 제안하는 기안문 초안" wide hint="수정한 내용만 반영됩니다.">
                  <TextInput value={draft} onChange={setDraft} multiline />
                </Field>
              </Form>
            </div>
          )}
        </Drawer>
      )}
    </div>
  );
}
